 1→/**
 2→ * TypeScript types for ZakupPro FastAPI backend
 3→ * Generated from Pydantic schemas in backend/schemas.py
 4→ */
 5→
 6→// =============================================================================
 7→// Base Types
 8→// =============================================================================
 9→
10→export type DateTime = string; // ISO 8601 datetime strings
11→
